examples.question_text:
The time $t$ in hours needed to complete a job varies inversely with the number of workers $n$. Use the labelled point on the graph to find the constant of variation and write the equation.

[tikz]
\begin{tikzpicture}
\definecolor{variationBlue}{HTML}{268CFF}
\definecolor{variationRed}{HTML}{EF6068}
\definecolor{variationGrid}{HTML}{CCCCCC}
\begin{axis}[width=70mm,height=60mm,axis lines=left,xmin=0,xmax=12,ymin=0,ymax=30,xtick={0,2,4,6,8,10,12},ytick={0,5,10,15,20,25,30},grid=major,grid style={draw=variationGrid},tick label style={font=\fontsize{8.5}{10}\selectfont,text=black},label style={font=\fontsize{10}{12}\selectfont,text=black},xlabel={Workers $n$},ylabel={Time $t$ (hours)},axis line style={draw=black},tick style={draw=black}]
\addplot[draw=variationBlue,thick,domain=2.4:12,samples=100] {72/x};
\addplot[only marks,mark=*,color=variationRed] coordinates {(6,12)};
\path (axis cs:6,12) node[above right,text=black,font=\fontsize{10}{12}\selectfont] {$(6,12)$};
\end{axis}
\end{tikzpicture}
[/tikz]
